  const id = encodeURIComponent(button.dataset.projectId);
  if (button.dataset.action === 'open') { location.href = `/projects/${id}`; return; }
  try { await request(`/api/projects/${id}/archive`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived: !archived }) }); await refresh(); }
  catch (error) { app.querySelector('#message').textContent = error.message; }
}));

