const archived = app.querySelector('#project-filter').value === 'Archived';
list.innerHTML = projects.filter(project => project.archived === archived).map(project => `<div class="row" data-testid="project-row"><span>${esc(project.name)}</span><span data-testid="project-summary">${project.completedCount}/${project.totalCount} completed</span><button type="button" data-action="open" data-project-id="${esc(project.id)}">Open project</button><button type="button" data-action="archive" data-project-id="${esc(project.id)}">${archived ? 'Restore project' : 'Archive project'}</button></div>`).join('');
list.querySelectorAll('button').forEach(button => button.addEventListener('click', async () => {
  const id = encodeURIComponent(button.dataset.projectId);
  if (button.dataset.action === 'open') { location.href = `/projects/${id}`; return; }
  try { await request(`/api/projects/${id}/archive`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived: !archived }) }); await refresh(); }
  catch (error) { app.querySelector('#message').textContent = error.message; }
}));

